import React, {useEffect, useRef} from 'react';
import {initLanding} from './landing.js';
import './landing.css';
import HeroModel3D from '../HeroModel3D';
import SemesterRacks from '../SemesterRacks';
import ProgressBackup from '../ProgressBackup';

// Review component. NativeViewer can be the original HeroModel3D wrapper.
export default function LandingPageV4({onModuleSelect, onSemesterSelect, semesters, onOpenLab}) {
 const root=useRef(null);
 useEffect(()=>initLanding(root.current,{onModuleSelect}),[onModuleSelect]);
 return <div ref={root} className="esl-v4-preview">
<a className={"skip"} href={"#utama"}>{"Langkau ke kandungan"}</a>
<header className={"header"}><div className={"wrap navrow"}><a className={"brand"} href={"#utama"} aria-label={"eSL-IKR Utama"}><img src={"data:image/webp;base64,"} alt={""} /><div><strong>{"eSL-"}<span>{"IKR"}</span></strong><small>{"eSmart Learning IKR"}</small></div></a><nav className={"nav"} aria-label={"Navigasi utama"}><a href={"#utama"} className={"active"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"}></path></svg>{" Utama"}</a><a href={"#semester"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m12 2 10 6-10 6L2 8zM2 12l10 6 10-6M2 16l10 6 10-6"}></path></svg>{" Modul"}</a><a href={"#makmal"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m12 3 9 5v8l-9 5-9-5V8zm0 9 9-4M12 12 3 8m9 4v9"}></path></svg>{" Makmal 3D"}</a><a href={"#panduan"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M12 7C9 4 5 4 2 5v15c4-1 7-1 10 2 3-3 6-3 10-2V5c-3-1-7-1-10 2v15"}></path></svg>{" Panduan"}</a></nav><button className={"search"} id={"searchBtn"} aria-label={"Cari modul"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><circle cx={"10.5"} cy={"10.5"} r={"7.5"}></circle><path d={"m16 16 5 5"}></path></svg><span>{"Cari modul, topik..."}</span><kbd>{"Ctrl K"}</kbd></button><ProgressBackup /><button id={"theme"} className={"iconbtn"} aria-label={"Tukar tema"} title={"Tukar tema"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><circle cx={"12"} cy={"12"} r={"4"}></circle><path d={"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"}></path></svg></button><button id={"menuBtn"} className={"iconbtn menu"} aria-label={"Buka menu"} aria-expanded={"false"} aria-controls={"mobileNav"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M4 6h16M4 12h16M4 18h16"}></path></svg></button></div><nav id={"mobileNav"} className={"wrap mobile-nav"} hidden aria-label={"Navigasi telefon"}><a href={"#utama"}>{"Utama"}</a><a href={"#semester"}>{"Modul"}</a><a href={"#makmal"}>{"Makmal 3D"}</a><a href={"#panduan"}>{"Panduan"}</a></nav></header>
<main id={"utama"}><section className={"wrap hero"}><div><div className={"eyebrow"}>{"eSmart Learning IKR · Teknologi Komputer Rangkaian"}</div><h1>{"Belajar komputer dan rangkaian."}<br /><span>{"Langkah demi langkah."}</span></h1><p className={"intro"}>{"Baru mengenali komputer dan rangkaian? Mulakan dengan nota, jawab kuiz, kemudian berlatih secara maya melalui dua makmal interaktif."}</p><div className={"actions"}><a className={"btn"} href={"#semester"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m8 4 13 8-13 8z"}></path></svg>{" Mula belajar "}<svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m9 18 6-6-6-6"}></path></svg></a><button className={"btn outline"} data-chooser={""}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m12 3 9 5v8l-9 5-9-5V8zm0 9 9-4M12 12 3 8m9 4v9"}></path></svg>{" Terokai Makmal 3D"}</button></div><div className={"stats"}><div className={"stat"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m12 2 10 6-10 6L2 8zM2 12l10 6 10-6M2 16l10 6 10-6"}></path></svg><div><b>{"16"}</b><span>{"Modul"}</span></div></div><div className={"stat"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m2 10 10-5 10 5-10 5zM6 12v5c3 3 9 3 12 0v-5m4-2v7"}></path></svg><div><b>{"3"}</b><span>{"Semester"}</span></div></div><div className={"stat"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><rect x={"2"} y={"3"} width={"20"} height={"14"} rx={"2"}></rect><path d={"M8 21h8m-4-4v4"}></path></svg><div><b>{"2"}</b><span>{"Makmal 3D"}</span></div></div></div></div><div className="native-viewer"><HeroModel3D src={`${import.meta.env.BASE_URL}models/gaming-pc.glb`} /><p className="viewerstatus">Tekan kiri atau kanan untuk menukar PC 3D dan Rack Server 3D. Pilih komponen untuk meneroka model.</p></div></section><section className={"learning"} aria-label={"Cara pembelajaran"}><div className={"wrap learning-heading"}><h2>{"Pertama kali di sini?"}</h2><p>{"Ikuti empat langkah untuk memulakan pembelajaran."}</p></div><div className={"wrap steps"}><div className={"step"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M12 7C9 4 5 4 2 5v15c4-1 7-1 10 2 3-3 6-3 10-2V5c-3-1-7-1-10 2v15"}></path></svg><div><b>{"01 · Belajar"}</b><p>{"Baca nota mengikut modul dan semester."}</p></div></div><div className={"step"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><circle cx={"10.5"} cy={"10.5"} r={"7.5"}></circle><path d={"m16 16 5 5"}></path></svg><div><b>{"02 · Fahami"}</b><p>{"Semak kefahaman melalui kuiz."}</p></div></div><div className={"step"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M14 6a5 5 0 0 0-6 6L3 17a2 2 0 0 0 3 3l5-5a5 5 0 0 0 6-6l-3 3-3-3z"}></path></svg><div><b>{"03 · Praktik"}</b><p>{"Jalankan amali dalam simulator 3D."}</p></div></div><div className={"step"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><rect x={"3"} y={"3"} width={"18"} height={"18"} rx={"2"}></rect><path d={"m7 12 3 3 7-7"}></path></svg><div><b>{"04 · Uji kemahiran"}</b><p>{"Cuba mod ujian amali."}</p></div></div></div></section><section className={"wrap section"} id={"semester"}><div className={"sectionhead"}><div className={"heading"}><h2>{"Pilih semester anda"}</h2><p>{"Terokai nota, topik dan kuiz mengikut tahap pembelajaran."}</p></div></div><div className="native-racks"><SemesterRacks semesters={semesters} onSelect={onSemesterSelect} /></div></section><section className={"labband"} id={"makmal"}><div id="pilih-makmal" className={"wrap section"}><div className={"sectionhead"}><div className={"heading"}><h2>{"Makmal Amali Interaktif"}</h2><p>{"Berlatih secara maya sebelum menggunakan perkakasan sebenar."}</p></div></div><div className={"labgrid"}><article className={"lab"}><img className={"labphoto"} src={"data:image/webp;base64,"} alt={"Komputer terbuka dengan perkakasan dalaman"} /><div className={"labbody"}><h3><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><rect x={"2"} y={"3"} width={"20"} height={"14"} rx={"2"}></rect><path d={"M8 21h8m-4-4v4"}></path></svg>{" Makmal PC 3D"}</h3><p>{"Kenali komponen, pasang perkakasan dan konfigurasi sistem operasi dalam persekitaran pembelajaran maya."}</p><div className={"tags"}><button type="button" className="tag" onClick={()=>onOpenLab('')}>Perkakasan</button><button type="button" className="tag" onClick={()=>onOpenLab('perisian')}>Perisian Windows</button><button type="button" className="tag" onClick={()=>onOpenLab('pembina')}>Pembina PC</button></div><a className={"btn outline"} href={`${import.meta.env.BASE_URL}pclab/index.html`}>{"Buka Makmal PC "}<svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M13 5h6v6m0-6-9 9m8 0v5H5V6h5"}></path></svg></a></div></article><article className={"lab"}><img className={"labphoto"} src={"data:image/webp;base64,"} alt={"Peralatan pengkabelan, kabel Ethernet, crimper dan patch panel"} /><div className={"labbody"}><h3><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M8 3v5m4-5v5M6 8h8v4a4 4 0 0 1-8 0zm4 8v2a3 3 0 0 0 6 0v-3m-2-4h6v4h-6z"}></path></svg>{" Structured Cabling 3D"}</h3><p>{"Berlatih menyusun wayar, melakukan crimping RJ45, menggunakan patch panel dan menguji sambungan kabel."}</p><div className={"tags"}><span className={"tag"}>{"RJ45"}</span><span className={"tag"}>{"Patch panel"}</span><span className={"tag"}>{"Cable tester"}</span></div><a className={"btn gold"} href={`${import.meta.env.BASE_URL}structured-cabling/index.html`}>{"Buka Makmal Cabling "}<svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M13 5h6v6m0-6-9 9m8 0v5H5V6h5"}></path></svg></a></div></article></div></div></section><section className={"wrap section"} id={"ciri"}><div className={"sectionhead"}><div className={"heading"}><h2>{"Satu portal untuk nota, simulasi dan ujian"}</h2><p>{"Rujukan teori dan latihan amali dalam satu tempat."}</p></div></div><div className={"featuregrid"}><article className={"feature visual-feature"}><img src={"data:image/webp;base64,"} alt={""} loading={"lazy"} /><h3>{"Belajar bab demi bab"}</h3><p>{"Setiap modul dibuka bab demi bab. Selesai membaca, bar kemajuan dan lencana dikemas kini pada peranti anda."}</p></article><article className={"feature visual-feature"}><img src={"data:image/webp;base64,"} alt={""} loading={"lazy"} /><h3>{"Lencana kemajuan"}</h3><p>{"Lulus kuiz dan lencana modul dibuka. Kemajuan disimpan dalam pelayar, tanpa akaun."}</p></article><article className={"feature visual-feature"}><img src={"data:image/webp;base64,"} alt={""} loading={"lazy"} /><h3>{"Satu makmal, empat alat"}</h3><p>{"Nota, kuiz, simulator pemasangan dan pembina PC 3D berada dalam portal yang sama. Tiada apa perlu dipasang."}</p></article><article className={"feature visual-feature"}><img src={"data:image/webp;base64,"} alt={""} loading={"lazy"} /><h3>{"Kemajuan yang boleh dilihat"}</h3><p>{"Lihat berapa bab sudah dibaca dan ke mana bacaan seterusnya patut menuju, sebelum ujian bermula."}</p></article></div></section><section className={"labband"} id={"panduan"}><div className={"wrap section guidegrid"}><div><div className={"eyebrow"}>{"Panduan pengguna"}</div><h2>{"Baru pertama kali?"}</h2><p>{"Mulakan daripada semester anda. Gunakan nota dan kuiz sebelum mencuba amali. Anda juga boleh terus membuka makmal untuk meneroka perkakasan."}</p><div className={"actions"} style={{"marginTop": "20px"}}><a className={"btn"} href={"#semester"}>{"Mula belajar "}<svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m9 18 6-6-6-6"}></path></svg></a></div><div className="guide-support-links"><a className="btn outline small" href="#faq">Soalan lazim</a><a className="btn outline small" href="#feedback">Beri maklum balas</a></div></div><div className="faq" id="faq" aria-labelledby="faqHeading"><h3 id="faqHeading">Soalan lazim (FAQ)</h3><p className="support-intro">Tekan soalan untuk melihat jawapan.</p><details open={true}><summary>Apa itu eSL-IKR?</summary><p>eSL-IKR ialah portal pembelajaran Teknologi Komputer Rangkaian yang menggabungkan nota, kuiz dan latihan amali maya.</p></details><details><summary>Saya tidak tahu apa-apa tentang komputer. Di mana perlu bermula?</summary><p>Mulakan di Semester 1 jika anda baharu. Baca modul Computer Hardware &amp; Software (IKR3013), kenali komponen, kemudian cuba latihan atau kuiz yang tersedia.</p></details><details><summary>Bagaimana saya mencari modul?</summary><p>Tekan Cari modul dan masukkan kod seperti IKR3043 atau kata kunci seperti VLAN dan firewall. Anda juga boleh memilih rack mengikut semester.</p></details><details><summary>Bagaimana saya menukar PC 3D kepada Rack Server 3D?</summary><p>Tekan anak panah kiri atau kanan pada satu pemapar di halaman utama. Pilih komponen untuk membaca penerangan ringkas. Model 3D langsung memerlukan internet dan peranti yang menyokong WebGL.</p></details><details><summary>Apakah perbezaan dua makmal?</summary><p>Makmal PC 3D menumpukan perkakasan, perisian Windows dan Pembina PC. Structured Cabling 3D menumpukan susunan wayar, crimping RJ45, patch panel dan pengujian kabel.</p></details><details><summary>Bolehkah saya menggunakan telefon?</summary><p>Ya, portal boleh dibuka menggunakan browser telefon. Untuk kerja amali yang memerlukan ruang paparan besar, komputer atau laptop lebih selesa.</p></details><details><summary>Adakah kemajuan saya disimpan?</summary><p>Kemajuan disimpan dalam pelayar pada peranti anda. Elakkan memadam data pelayar jika mahu mengekalkan kemajuan. Gunakan fungsi sandaran kemajuan jika perlu.</p></details><details><summary>Bagaimana jika ada masalah atau cadangan?</summary><p>Gunakan borang maklum balas di bawah. Nyatakan bahagian yang bermasalah dan langkah yang anda lakukan supaya pasukan dapat memahami isu tersebut.</p></details></div></div></section><section id="feedback" className="wrap section feedback-section" aria-labelledby="feedbackHeading"><div className="feedback-layout"><div className="feedback-copy"><div className="eyebrow">Maklum balas pengguna</div><h2 id="feedbackHeading">Bantu kami menambah baik eSL-IKR.</h2><p>Adakah portal ini mudah difahami? Kongsi pengalaman anda supaya kami boleh memperbaiki pembelajaran dan simulasi.</p><div className="feedback-note"><strong>Privasi anda</strong><p>Tidak perlu nama, emel atau nombor telefon. Jangan masukkan maklumat peribadi dalam ulasan.</p></div><a className="btn outline small" href="#faq">Lihat FAQ ↑</a></div><form id="feedbackForm" className="feedback-form"><fieldset><legend>Sejauh mana portal mudah difahami? <span className="required-mark">*</span></legend><div className="feedback-ratings"><label><input type="radio" name="rating" value="1" required aria-label="1 daripada 5"/><span>1</span></label><label><input type="radio" name="rating" value="2" required aria-label="2 daripada 5"/><span>2</span></label><label><input type="radio" name="rating" value="3" required aria-label="3 daripada 5"/><span>3</span></label><label><input type="radio" name="rating" value="4" required aria-label="4 daripada 5"/><span>4</span></label><label><input type="radio" name="rating" value="5" required aria-label="5 daripada 5"/><span>5</span></label></div><div className="rating-labels"><span>Sangat sukar</span><span>Sangat mudah</span></div></fieldset><label htmlFor="feedbackCategory">Bahagian yang ingin dinilai <span className="required-mark">*</span></label><select id="feedbackCategory" name="category" required><option value="">Pilih bahagian</option><option>Landing page dan navigasi</option><option>Nota dan kuiz</option><option>Makmal PC 3D</option><option>Structured Cabling 3D</option><option>Light Mode / Dark Mode</option><option>Masalah teknikal</option><option>Lain-lain</option></select><label htmlFor="feedbackMessage">Cadangan atau masalah <span className="optional-mark">(pilihan)</span></label><textarea id="feedbackMessage" name="message" rows="4" maxLength="1000" placeholder="Contoh: Saya tidak pasti di mana perlu bermula…"></textarea><p className="feedback-counter" id="feedbackCounter">0 / 1000</p><p className="feedback-local">Maklum balas disediakan sebagai fail teks untuk dikongsi sendiri. Ia tidak dihantar secara automatik kepada pasukan.</p><div className="feedback-actions"><button type="submit" className="btn">Sediakan maklum balas</button><button type="button" className="btn outline" id="feedbackReset">Kosongkan</button></div><p id="feedbackStatus" className="feedback-status" role="status" aria-live="polite"></p><div id="feedbackExport" className="feedback-export" hidden><button type="button" className="btn outline small" id="feedbackDownload">Muat turun .txt</button><button type="button" className="btn outline small" id="feedbackCopy">Salin maklum balas</button><textarea id="feedbackOutput" readOnly aria-label="Maklum balas untuk dikongsi" rows="5"></textarea></div></form></div></section></main>
<footer className={"footer"}><div className={"wrap"}><img className={"institution"} src={"data:image/webp;base64,"} alt={"ADTEC JTM Kampus Sandakan dan eSL-IKR"} /><div className={"brand"}><img src={"data:image/webp;base64,"} alt={""} /><div><strong>{"eSL-"}<span>{"IKR"}</span></strong><small>{"eSmart Learning IKR"}</small></div></div><div><p>{"Teknologi Komputer Rangkaian · ADTEC JTM Kampus Sandakan"}</p><div className={"prototype"}>{"Copyright © TKR ADTEC Sandakan 2026"}</div></div><a className={"btn outline small"} href="#utama">{"Kembali ke atas "}<svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"M13 5h6v6m0-6-9 9m8 0v5H5V6h5"}></path></svg></a></div></footer>
<dialog className={"dialog"} id={"dialog"} aria-labelledby={"dialogTitle"}><div className={"dialoghead"}><h2 id={"dialogTitle"}>{"Cari modul"}</h2><button className={"iconbtn"} id={"closeDialog"} aria-label={"Tutup"}><svg className={"ico"} viewBox={"0 0 24 24"} aria-hidden={"true"}><path d={"m6 6 12 12M6 18 18 6"}></path></svg></button></div><div className={"dialogbody"} id={"dialogBody"}></div></dialog>
</div>;
}
